mapper.select:
SELECT m.movie_asin, m.movie_title, m.score, GROUP_CONCAT(DISTINCT a.name ORDER BY a.name SEPARATOR ', ') AS actors, GROUP_CONCAT(DISTINCT d.name ORDER BY d.name SEPARATOR ', ') AS directors, GROUP_CONCAT(DISTINCT mg.genre ORDER BY mg.genre SEPARATOR ', ') AS genres, CONCAT(rd.year, '-', LPAD(rd.month, 2, '0'), '-', LPAD(rd.day, 2, '0')) AS release_date, GROUP_CONCAT(DISTINCT me.edition ORDER BY me.edition SEPARATOR ', ') AS editions FROM movies m LEFT JOIN movie_actors ma ON m.id = ma.movie_id LEFT JOIN actors a ON ma.actor_id = a.id LEFT JOIN movie_directors md ON m.id = md.movie_id LEFT JOIN directors d ON md.director_id = d.id LEFT JOIN movie_genres mg ON m.id = mg.movie_id LEFT JOIN release_dates rd ON m.id = rd.movie_id LEFT JOIN movie_editions me ON m.id = me.movie_id WHERE 1=1
AND LOWER(m.movie_title) LIKE CONCAT('%', LOWER(#{dto.movieTitle}), '%')
AND LOWER(a.name) LIKE CONCAT('%', LOWER(#{dto.actorName}), '%')
AND LOWER(d.name) LIKE CONCAT('%', LOWER(#{dto.directorName}), '%')
AND LOWER(mg.genre) LIKE CONCAT('%', LOWER(#{dto.movieGenre}), '%')
AND rd.year >= #{dto.startYear}
AND rd.year <= #{dto.endYear}
AND rd.month = #{dto.month}
AND rd.day = #{dto.day}
AND m.score >= #{dto.minScore}
AND m.score <= #{dto.maxScore}
GROUP BY m.id, m.movie_asin, m.movie_title, m.score, rd.year, rd.month, rd.day ORDER BY m.movie_title
LIMIT #{dto.size} OFFSET #{dto.page}

SELECT 
    movie_asin AS movieAsin,
    movie_title AS movieTitle,
    movie_score AS movieScore,
    actor_names AS actors,
    director_names AS directors,
    movie_genre AS movieGenre,
    CONCAT(release_year, '-', LPAD(release_month, 2, '0'), '-', LPAD(release_day, 2, '0')) AS release_date,
    edition_list AS edition
FROM movie_denormalization


        AND release_year >= #{dto.startYear}


        AND release_year <= #{dto.endYear}




        AND movie_title LIKE CONCAT('%', #{dto.movieTitle}, '%')



        AND actor_names LIKE CONCAT('%', #{dto.actorName}, '%')


        AND director_names LIKE CONCAT('%', #{dto.directorName}, '%')


        AND movie_genre LIKE CONCAT('%', #{dto.movieGenre}, '%')


    AND release_month = #{dto.month}
    AND release_day = #{dto.day}
    AND movie_score >= #{dto.minScore}
    AND movie_score <= #{dto.maxScore}

ORDER BY movie_title

    LIMIT #{dto.size} OFFSET #{dto.page}

SELECT COUNT(DISTINCT m.id) FROM movies m LEFT JOIN movie_actors ma ON m.id = ma.movie_id LEFT JOIN actors a ON ma.actor_id = a.id LEFT JOIN movie_directors md ON m.id = md.movie_id LEFT JOIN directors d ON md.director_id = d.id LEFT JOIN movie_genres mg ON m.id = mg.movie_id LEFT JOIN release_dates rd ON m.id = rd.movie_id LEFT JOIN movie_editions me ON m.id = me.movie_id WHERE 1=1
AND ( (dto.movieTitle != null and dto.movieTitle != '') or (dto.actorName != null and dto.actorName != '') or (dto.directorName != null and dto.directorName != '') or (dto.movieGenre != null and dto.movieGenre != '') or (dto.startYear > 0) or (dto.endYear > 0) or (dto.month > 0) or (dto.weekday > 0) or (dto.day > 0) )
AND LOWER(m.movie_title) LIKE CONCAT('%', LOWER(#{dto.movieTitle}), '%')
AND LOWER(a.name) LIKE CONCAT('%', LOWER(#{dto.actorName}), '%')
AND LOWER(d.name) LIKE CONCAT('%', LOWER(#{dto.directorName}), '%')
AND LOWER(mg.genre) LIKE CONCAT('%', LOWER(#{dto.movieGenre}), '%')
AND rd.year >= #{dto.startYear}
AND rd.year <= #{dto.endYear}
AND rd.month = #{dto.month}
AND rd.day = #{dto.day}
AND m.score >= #{dto.minScore}
AND m.score <= #{dto.maxScore}
